"""Generate packages/contracts/outcomes.schema.json and outcomes.ts from the models of the outcomes API (job DM, C1 part). Same scheme as the other contracts (`make contracts`; a test fails if either file
is stale). Committed early: the customer timeline and Today are built against it."""

from __future__ import annotations

import json
from typing import Any

from pydantic import BaseModel
from pydantic.json_schema import models_json_schema

from app.outcomes import models as m
from app.packs.contracts import _ts_type

HEADER = (
    "// GENERATED by `make contracts` from services/ai-api/app/outcomes/models.py. Do not edit.\n"
    "// An outcome of one call or one WhatsApp follow-up conversation: positive | negative | unclear, a category and a short reason. No child data.\n"
)
RESPONSES: list[type[BaseModel]] = [m.OutcomeOut, m.OutcomeRecordedOut, m.OutcomeListOut, m.OutcomeTotalsOut, m.CustomerOutcomeOut]
REQUESTS: list[type[BaseModel]] = [m.OutcomeIn, m.OutcomeCorrectionIn, m.CustomerCorrectionIn]


def build_schema() -> dict[str, Any]:
    _, defs = models_json_schema(
        [(model, "serialization") for model in RESPONSES] + [(model, "validation") for model in REQUESTS], ref_template="#/$defs/{model}"
    )
    return {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": "outcomes.schema.json",
        "title": "Outcomes of calls and WhatsApp follow-ups (job DM)",
        "description": "Generated from services/ai-api/app/outcomes/models.py by `make contracts`.",
        "$defs": dict(sorted(defs.get("$defs", {}).items())),
    }


def schema_text() -> str:
    return json.dumps(build_schema(), indent=2, sort_keys=False) + "\n"


def ts_text() -> str:
    defs = build_schema()["$defs"]
    lines = [HEADER]
    for name, node in defs.items():
        ts_name = name.replace("_", "")
        if "enum" in node:
            lines.append(f"export type {ts_name} = {_ts_type(node)};\n")
            continue
        props = node.get("properties", {})
        required = set(node.get("required", []))
        body = []
        for prop, spec in props.items():
            optional = "" if prop in required else "?"
            body.append(f"  {prop}{optional}: {_ts_type(spec)};")
        lines.append(f"export interface {ts_name} {{\n" + "\n".join(body) + "\n}\n")
    return "\n".join(lines)
